import{_ as n,C as s,o as d,c as e,a3 as r,j as i,E as o,a as l}from"./chunks/framework.C6R8kWFE.js";const E=JSON.parse('{"title":"9-dars (Mentor). Simulyator va Emulator haqida tushuncha (1-qism)","description":"","frontmatter":{"title":"9-dars (Mentor). Simulyator va Emulator haqida tushuncha (1-qism)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Android)","link":"/mentor/9-sinf-android/"},"week":{"n":3,"link":"/mentor/9-sinf-android/hafta-03/"},"g":9,"title":"Simulyator va Emulator haqida tushuncha (1-qism)","lead":"Simulyator va Emulator haqida tushuncha (1-qism): Simulyator vs Emulyator farqi, AVD yaratish va CPU virtualizatsiyasi","slide":"/slaydlar/9-sinf-android/hafta-03/dars-3.html","test":"/slaydlar/9-sinf-android/hafta-03/dars-3-test.html","student_link":"/9-sinf-android/hafta-03/dars-3","tabs":[{"g":7,"link":"/mentor/9-sinf-android/hafta-03/dars-1","current":false},{"g":8,"link":"/mentor/9-sinf-android/hafta-03/dars-2","current":false},{"g":9,"link":"/mentor/9-sinf-android/hafta-03/dars-3","current":true}],"prev":{"g":8,"title":"Android Studio va Android SDK bilan tanishuv (3-qism)","link":"/mentor/9-sinf-android/hafta-03/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/9-sinf-android/hafta-03/dars-3.md","filePath":"mentor/9-sinf-android/hafta-03/dars-3.md"}'),u={name:"mentor/9-sinf-android/hafta-03/dars-3.md"},m={class:"blk"},h={id:"_1-dars-maqsadi-va-kutiladigan-natijalar",tabindex:"-1"},y={class:"blk"},g={id:"_2-dars-rejasi-80-daqiqa",tabindex:"-1"},q={class:"blk"},v={id:"_3-nazariy-tushunchalar-mentor-uchun-to-liq-konspekt",tabindex:"-1"},k={class:"blk"},b={id:"_4-darsda-bajariladigan-amaliy-topshiriqlar-va-yechimlari",tabindex:"-1"},p={class:"blk"},f={id:"_5-tezkor-savol-javob-blits-savollar",tabindex:"-1"},c={class:"blk"},_={id:"_6-mentor-uchun-amaliy-tavsiyalar",tabindex:"-1"};function z(S,a,A,x,T,V){const t=s("Icon");return d(),e("div",null,[a[18]||(a[18]=r("<p><strong>Sinf:</strong> 9-sinf (Android dasturlash)<br><strong>Hafta:</strong> 3-hafta<br><strong>Dars tartibi:</strong> 9-dars (umumiy 102 darsdan 9-darsi)<br><strong>Davomiyligi:</strong> 80 daqiqa<br><strong>Format:</strong> Nazariy va amaliy laboratoriya mashg&#39;uloti</p><hr>",2)),i("div",m,[i("h2",h,[o(t,{name:"file-text"}),a[0]||(a[0]=l(" 1. Dars maqsadi va kutiladigan natijalar ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-maqsadi-va-kutiladigan-natijalar","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars maqsadi va kutiladigan natijalar"'},"​",-1))]),a[2]||(a[2]=r("<ul><li><strong>Maqsad:</strong> O&#39;quvchilarga mobil dasturlashda testlash muhiti — Simulyator va Emulyator o&#39;rtasidagi fundamental farq, Android Virtual Device (AVD) yaratish va sozlash, kompyuter protsessorida apparat virtualizatsiyasining (Intel VT-x / AMD-V) roli hamda emulyator imkoniyatlarini o&#39;rgatish.</li><li><strong>Kutiladigan natijalar:</strong><ul><li>O&#39;quvchi Simulyator (Simulator) va Emulyator (Emulator) o&#39;rtasidagi texnik farqni tushuntira oladi;</li><li>AVD Manager oynasi orqali yangi virtual qurilma yarata oladi (qurilma modeli, tizim tasviri, RAM hajmi);</li><li>Protsessor virtualizatsiyasi (Intel VT-x, AMD-V, KVM) nima uchun emulyator tezligi uchun zarurligini biladi;</li><li>Emulyatorning yon boshqaruv panelidagi vositalardan (aylantirish, ovoz, kamera, GPS taqlidi, batareya holati) foydalana oladi;</li><li>Virtual qurilma va real smartfonda testlashning afzallik va kamchiliklarini taqqoslay oladi.</li></ul></li></ul><hr>",2))]),i("div",y,[i("h2",g,[o(t,{name:"file-text"}),a[3]||(a[3]=l(" 2. Dars rejasi (80 daqiqa) ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-rejasi-80-daqiqa","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars rejasi (80 daqiqa)"'},"​",-1))]),a[5]||(a[5]=r('<table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Tavsif</th></tr></thead><tbody><tr><td><strong>00–10 daq</strong></td><td>O&#39;tgan mavzuni takrorlash va kirish</td><td>«Hello World» ilovasi, setContentView, TextView bo&#39;yicha blits-so&#39;rov. Muammoli savol: &quot;Hamma dasturchida 10 ta har xil telefon bormi? Ular ilovani turli ekranlarda qanday tekshiradi?&quot;</td></tr><tr><td><strong>10–30 daq</strong></td><td>Yangi mavzu: Simulyator vs Emulyator</td><td>Tashqi xatti-harakatni taqlid qilish (Simulation) vs Apparatni modellashtirish (Emulation), Android Emulator tuzilishi</td></tr><tr><td><strong>30–50 daq</strong></td><td>Yangi mavzu: AVD Manager va Virtualizatsiya</td><td>AVD yaratish bosqichlari (Device, System Image: Google APIs vs AOSP), Intel VT-x va AMD-V nima uchun kerak?</td></tr><tr><td><strong>50–65 daq</strong></td><td>Yangi mavzu: Emulyatorning interaktiv paneli</td><td>Yon panel: GPS koordinatalarini uzatish, qo&#39;ng&#39;iroq va SMS simulyatsiyasi, ekranni aylantirish va skrinshot olish</td></tr><tr><td><strong>65–75 daq</strong></td><td>Amaliy mashq va laboratoriya</td><td>O&#39;quvchilar bilan kompyuterda AVD qurilmasini ishga tushirish va uning sozlamalarini o&#39;rganish</td></tr><tr><td><strong>75–80 daq</strong></td><td>Xulosa va 3-hafta sarhisobi</td><td>Dars yakunlari, o&#39;quvchilarni baholash, 3-haftaning umumiy uyga vazifasini topshirish</td></tr></tbody></table><hr>',2))]),i("div",q,[i("h2",v,[o(t,{name:"file-text"}),a[6]||(a[6]=l(" 3. Nazariy tushunchalar (Mentor uchun to'liq konspekt) ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-nazariy-tushunchalar-mentor-uchun-to-liq-konspekt","aria-label":`Permalink to "<Icon name="file-text" /> 3. Nazariy tushunchalar (Mentor uchun to'liq konspekt)"`},"​",-1))]),a[8]||(a[8]=r('<h3 id="_3-1-simulyator-va-emulyator-o-rtasidagi-fundamental-farq" tabindex="-1">3.1. Simulyator va Emulyator o&#39;rtasidagi fundamental farq <a class="header-anchor" href="#_3-1-simulyator-va-emulyator-o-rtasidagi-fundamental-farq" aria-label="Permalink to &quot;3.1. Simulyator va Emulyator o&#39;rtasidagi fundamental farq&quot;">​</a></h3><p>Ko&#39;pincha bu ikki atama yanglish holda bir xil ma&#39;noda ishlatiladi, ammo ular tubdan farq qiladi:</p><ol><li><strong>Simulyator (Simulator):</strong><ul><li>Faqat tashqi interfeys va dasturiy qoidalarni taqlid qiladi.</li><li>U apparat qismlarini (protsessor registrlarini, xotira kontrollerlarini) modellashtirmaydi, balki kompyuterning o&#39;z arxitekturasida ishlaydi (masalan, iOS Simulator Mac kompyuterining x86 yoki ARM64 yadrolarida bevosita ishlaydi).</li><li><em>Kamchiligi:</em> Haqiqiy telefon apparatida (masalan, xotira yetishmovchiligida yoki sensorlar ishlashida) yuzaga keladigan real muammolarni aniqlay olmaydi.</li></ul></li><li><strong>Emulyator (Emulator):</strong><ul><li>Haqiqiy qurilmaning butun apparat ta&#39;minotini (Hardware) to&#39;liq dasturiy modellashtiradi: virtual CPU, virtual RAM, virtual Bluetooth, modem va kamera drayverlari.</li><li><strong>Android Emulator (QEMU negizida):</strong> Haqiqiy Android operatsion tizimi virtual qurilma ichida noldan yuklanadi (boot bo&#39;ladi). U apparat ta&#39;minotining barcha cheklovlari va xatti-harakatlarini 100% aks ettiradi.</li></ul></li></ol><h3 id="_3-2-avd-android-virtual-device-manager" tabindex="-1">3.2. AVD (Android Virtual Device) Manager <a class="header-anchor" href="#_3-2-avd-android-virtual-device-manager" aria-label="Permalink to &quot;3.2. AVD (Android Virtual Device) Manager&quot;">​</a></h3><p>AVD — bu kompyuteringiz xotirasida saqlanadigan virtual smartfon yoki planshet konfiguratsiyasidir. Uni yaratishda 4 ta asosiy parametr tanlanadi:</p><ol><li><strong>Hardware Profile (Apparat profili):</strong> Qurilma modeli (masalan, Pixel 8 Pro), ekranning fizik o&#39;lchami (6.7 dyuym) va piksellar aniqligi (1344 x 2992, 489 dpi);</li><li><strong>System Image (Tizim tasviri):</strong> Android versiyasi (Android 14 API 34). Tavsiya etiladigan variant: <strong>Google APIs (x86_64)</strong> — bu variant kompyuter protsessorida tez ishlaydi va Google Play Services xizmatlariga ega;</li><li><strong>Memory and Storage (Xotira):</strong> Emulyator uchun ajratiladigan RAM (masalan, 2048 MB) va ichki xotira (masalan, 6 GB);</li><li><strong>Graphics Emulation:</strong> <code>Hardware - GLES 2.0</code> — kompyuteringizning videokartasidan (GPU) foydalanib, emulyator grafikasini 60 kadr/soniya (fps) tezlikda silliq ko&#39;rsatish.</li></ol><h3 id="_3-3-protsessor-virtualizatsiyasi-hardware-virtualization" tabindex="-1">3.3. Protsessor virtualizatsiyasi (Hardware Virtualization) <a class="header-anchor" href="#_3-3-protsessor-virtualizatsiyasi-hardware-virtualization" aria-label="Permalink to &quot;3.3. Protsessor virtualizatsiyasi (Hardware Virtualization)&quot;">​</a></h3><p>Nima uchun ba&#39;zi kompyuterlarda emulyator umuman ochilmaydi?</p><ul><li>Emulyator kompyuter ichida butun bir operatsion tizimni ishga tushirishi sababli, unga apparat tezlatgichi kerak bo&#39;ladi.</li><li><strong>Intel protsessorlarida:</strong> <code>Intel VT-x</code> (Virtualization Technology);</li><li><strong>AMD protsessorlarida:</strong> <code>AMD-V</code> (SVM);</li><li><strong>Apple Silicon (M1/M2/M3/M4):</strong> ARM-to-ARM to&#39;g&#39;ridan-to&#39;g&#39;ri virtualizatsiya (Hypervisor Framework).</li><li>Agar kompyuter BIOS/UEFI sozlamalarida virtualizatsiya o&#39;chirilgan bo&#39;lsa, emulyator bir necha daqiqalab ochiladi yoki qotib qoladi. Shuning uchun BIOS&#39;da virtualizatsiya yoqilgan bo&#39;lishi shart!</li></ul><h3 id="_3-4-emulyatorning-kengaytirilgan-boshqaruv-paneli-extended-controls" tabindex="-1">3.4. Emulyatorning kengaytirilgan boshqaruv paneli (Extended Controls) <a class="header-anchor" href="#_3-4-emulyatorning-kengaytirilgan-boshqaruv-paneli-extended-controls" aria-label="Permalink to &quot;3.4. Emulyatorning kengaytirilgan boshqaruv paneli (Extended Controls)&quot;">​</a></h3><p>Emulyator oynasining yon tomonidagi vertikal asboblar paneli orqali dasturchi hayotiy ssenariylarni sinab ko&#39;radi:</p><ul><li><strong>Location (GPS):</strong> Xaritadan istalgan nuqtani (masalan, Toshkent, Samarqand yoki Parij) tanlab, ilovaga soxta GPS koordinatalarini yuborish;</li><li><strong>Cellular &amp; Battery:</strong> Batareya zaryadini 10% qilib, ilova kam quvvatda qanday ishlashini yoki tarmoq tezligini &quot;LTE&quot; dan &quot;GPRS&quot; ga tushirib sinash;</li><li><strong>Phone:</strong> Virtual telefonga qo&#39;ng&#39;iroq qilish yoki SMS yuborish;</li><li><strong>Camera:</strong> Kompyuter veb-kamerasini virtual telefon kamerasi sifatida ulash;</li><li><strong>Display:</strong> Ekranni 90 darajaga aylantirib (Landscape), ilovaning gorizontal ko&#39;rinishini tekshirish.</li></ul><hr>',13))]),i("div",k,[i("h2",b,[o(t,{name:"file-text"}),a[9]||(a[9]=l(" 4. Darsda bajariladigan amaliy topshiriqlar va yechimlari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-darsda-bajariladigan-amaliy-topshiriqlar-va-yechimlari","aria-label":'Permalink to "<Icon name="file-text" /> 4. Darsda bajariladigan amaliy topshiriqlar va yechimlari"'},"​",-1))]),a[11]||(a[11]=r('<h3 id="_1-topshiriq-simulyator-va-emulyator-taqqoslash-matritsasi-oson" tabindex="-1">1-topshiriq. Simulyator va Emulyator taqqoslash matritsasi (Oson) <a class="header-anchor" href="#_1-topshiriq-simulyator-va-emulyator-taqqoslash-matritsasi-oson" aria-label="Permalink to &quot;1-topshiriq. Simulyator va Emulyator taqqoslash matritsasi (Oson)&quot;">​</a></h3><p><strong>Topshiriq:</strong> Simulyator va Emulyator tushunchalarini ishlash prinsipi va apparat modellashtirishi bo&#39;yicha taqqoslang.</p><p><strong>Yechim:</strong></p><table tabindex="0"><thead><tr><th>Xususiyat</th><th>Simulyator (Simulator)</th><th>Emulyator (Emulator)</th></tr></thead><tbody><tr><td>Modellashtirish darajasi</td><td>Faqat dasturiy interfeys va xatti-harakat</td><td>To&#39;liq apparat ta&#39;minoti (CPU, xotira, datchiklar)</td></tr><tr><td>Tezlik</td><td>Juda tez (kompyuter kodi kabi)</td><td>O&#39;rtacha (virtualizatsiyaga bog&#39;liq)</td></tr><tr><td>Aniqlik</td><td>O&#39;rtacha</td><td>Haqiqiy telefonga 99% yaqin</td></tr><tr><td>Misol</td><td>Apple iOS Simulator</td><td>Android Virtual Device (AVD)</td></tr></tbody></table><h3 id="_2-topshiriq-virtualizatsiya-muammosi-diagnostikasi-o-rta" tabindex="-1">2-topshiriq. Virtualizatsiya muammosi diagnostikasi (O&#39;rta) <a class="header-anchor" href="#_2-topshiriq-virtualizatsiya-muammosi-diagnostikasi-o-rta" aria-label="Permalink to &quot;2-topshiriq. Virtualizatsiya muammosi diagnostikasi (O&#39;rta)&quot;">​</a></h3><p><strong>Topshiriq:</strong> O&#39;quvchi Android Studio&#39;da yangi AVD yaratdi, ammo emulyator ishga tushmayapti va quyidagi xatolik chiqmoqda:<br><code>&quot;HAXM is not installed / VT-x is disabled in BIOS&quot;</code>.<br> Bu xatolik nimani bildiradi va uni qanday tuzatish kerak?</p><p><strong>Yechim:</strong></p><ul><li><strong>Sababi:</strong> Kompyuterning markaziy protsessorida (CPU) apparat virtualizatsiyasi (Intel VT-x yoki AMD-V) BIOS/UEFI darajasida o&#39;chirilgan (Disabled).</li><li><strong>Tuzatish tartibi:</strong><ol><li>Kompyuterni qayta ishga tushirib (Restart), BIOS/UEFI menyusiga kiriladi (F2, F10 yoki Del tugmasi orqali);</li><li>&quot;Advanced&quot; yoki &quot;Security&quot; -&gt; &quot;CPU Configuration&quot; bo&#39;limi topiladi;</li><li>&quot;Intel Virtualization Technology&quot; (yoki &quot;SVM Mode&quot;) parametri <strong>&quot;Enabled&quot;</strong> qilinadi va sozlamalar saqlanadi (F10);</li><li>Kompyuter yoqilgach, Android Studio&#39;da emulyator darhol tezkor ishga tushadi.</li></ol></li></ul><h3 id="_3-topshiriq-gps-simulyatsiyasi-keysi-qiyin" tabindex="-1">3-topshiriq. GPS simulyatsiyasi keysi (Qiyin) <a class="header-anchor" href="#_3-topshiriq-gps-simulyatsiyasi-keysi-qiyin" aria-label="Permalink to &quot;3-topshiriq. GPS simulyatsiyasi keysi (Qiyin)&quot;">​</a></h3><p><strong>Topshiriq:</strong> Siz taksi chaqirish ilovasini (masalan, Yandex Go yoki MyTaxi muqobilini) yaratmoqchisiz. Emulyatorda mashina harakatlanayotganini real smartfonsiz qanday tekshirish mumkin?</p><p><strong>Yechim:</strong></p><ol><li>Emulyatorning yon panelidagi uch nuqta <code>...</code> (Extended controls) tugmasi bosiladi;</li><li><strong>Location</strong> bo&#39;limiga o&#39;tiladi;</li><li>&quot;Routes&quot; yorlig&#39;ida boshlang&#39;ich va yakuniy manzil kiritiladi yoki GPX/KML fayli yuklanadi;</li><li>&quot;Play Route&quot; tugmasi bosilganda, emulyator belgilangan tezlikda (masalan, 40 km/soat) koordinatalarni ketma-ket uzatishni boshlaydi. Ilova xaritadagi avtomobil harakatini xuddi haqiqiy hayotdagidek chizadi.</li></ol><hr>',13))]),i("div",p,[i("h2",f,[o(t,{name:"file-text"}),a[12]||(a[12]=l(" 5. Tezkor savol-javob (Blits-savollar) ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_5-tezkor-savol-javob-blits-savollar","aria-label":'Permalink to "<Icon name="file-text" /> 5. Tezkor savol-javob (Blits-savollar)"'},"​",-1))]),a[14]||(a[14]=r("<ol><li><strong>AVD qisqartmasi nimani anglatadi?</strong><br><em>Javob:</em> Android Virtual Device (Android virtual qurilmasi).</li><li><strong>Emulyatorning simulyatordan asosiy farqi nima?</strong><br><em>Javob:</em> Emulyator qurilmaning apparat ta&#39;minotini (hardware) to&#39;liq modellashtiradi, simulyator esa faqat dasturiy qobiqni taqlid qiladi.</li><li><strong>Intel protsessorlarida virtualizatsiya qanday nomlanadi?</strong><br><em>Javob:</em> Intel VT-x.</li><li><strong>Emulyator sozlamalarida &quot;Google APIs&quot; tasvirining qanday afzalligi bor?</strong><br><em>Javob:</em> Unda Google Maps, Google Sign-In va Firebase xizmatlari oldindan o&#39;rnatilgan bo&#39;ladi.</li><li><strong>Emulyatorda ekranni aylantirish uchun nima qilinadi?</strong><br><em>Javob:</em> Yon boshqaruv panelidagi &quot;Rotate left / Rotate right&quot; tugmasi bosiladi.</li></ol><hr>",2))]),i("div",c,[i("h2",_,[o(t,{name:"file-text"}),a[15]||(a[15]=l(" 6. Mentor uchun amaliy tavsiyalar ",-1)),a[16]||(a[16]=i("a",{class:"header-anchor",href:"#_6-mentor-uchun-amaliy-tavsiyalar","aria-label":'Permalink to "<Icon name="file-text" /> 6. Mentor uchun amaliy tavsiyalar"'},"​",-1))]),a[17]||(a[17]=i("ul",null,[i("li",null,"O'quvchilarga emulyatorning Extended Controls oynasida GPS koordinatasini o'zgartirish qanday ishlashini ko'rsating."),i("li",null,"Agar kompyuterlarning RAM xotirasi kam bo'lsa (8 GB dan kam), keyingi darsda real telefonni USB kabel orqali ulab testlashni (USB Debugging) o'rganishimizni bildiring.")],-1))])])}const D=n(u,[["render",z]]);export{E as __pageData,D as default};
